"""Integration checks against the artifacts generated by run.sh, without replacing them."""

import json
import subprocess
import sys
import unittest
from math import fsum
from pathlib import Path
from tempfile import TemporaryDirectory

from forecast.history import DAY, HOUR, History
from forecast.model import Model

ROOT = Path(__file__).resolve().parents[1]
BUILD = ROOT / ".work" / "build"
INGEST = BUILD / "ingest"
OUT = ROOT / "out"
CUTOFF = 1738713600


def run(*args: str | Path | int) -> str:
    return subprocess.run([str(arg) for arg in args], cwd=ROOT, check=True,
                          stdout=subprocess.PIPE, text=True, timeout=60).stdout


def cli(*args: str | Path | int) -> dict:
    return json.loads(run(sys.executable, "-B", "-s", "-m", "forecast", *args))


class PipelineTests(unittest.TestCase):
    def setUp(self) -> None:
        scratch = TemporaryDirectory(dir=BUILD)
        self.addCleanup(scratch.cleanup)
        self.work = Path(scratch.name)

    def test_cli_parity_and_mae_on_every_heldout_hour(self) -> None:
        events, artifact = OUT / "events.csv", OUT / "model-v1.json"
        h, model = History.load(events), Model.load(artifact)
        rows = [json.loads(line) for line in (OUT / "heldout.jsonl").read_text().splitlines()]
        metrics = json.loads((OUT / "metrics.json").read_text())
        self.assertEqual(model.training_start, h.start + DAY)
        self.assertEqual(model.last_training_origin + HOUR + h.lateness, CUTOFF)
        self.assertEqual([r["origin"] for r in rows], list(range(CUTOFF, h.end - h.lateness, HOUR)))
        for row in rows:
            t = row["origin"]
            self.assertEqual(row, {**model.forecast(h, t), "actual": h.label(t, h.through)})
        for field, key in [("prediction", "model_mae"), ("seasonal", "seasonal_mae")]:
            self.assertEqual(metrics[key], fsum(abs(r[field] - r["actual"]) for r in rows) / len(rows))
        self.assertEqual(len(rows), metrics["test_rows"])
        for row in (rows[0], rows[len(rows) // 2], rows[-1]):
            self.assertEqual(cli("predict", events, artifact, row["origin"]),
                             {k: v for k, v in row.items() if k != "actual"})
        self.assertEqual(cli("predict", events, artifact, h.end)["target_end"], h.end + HOUR)
        with self.assertRaises(ValueError):
            h.label(h.end, h.through)

    def test_changed_future_and_late_facts_leave_fit_and_issue_unchanged(self) -> None:
        events, original = OUT / "events.csv", OUT / "model-v1.json"
        lines = events.read_text().splitlines()
        issue = CUTOFF + HOUR  # Two prior-hour facts first arrive after this issue.
        changed, prefix = lines[:2], lines[:2]
        prefix[0] = prefix[0].rsplit(",", 1)[0] + f",{issue}"
        late_history, future = 0, 0
        for line in lines[2:]:
            event, occurred, received, units = line.split(",")
            if int(received) > issue:
                line = f"{event},{occurred},{received},{int(units) + 200}"
                if int(occurred) < issue:
                    late_history += 1
                else:
                    future += 1
            else:
                prefix.append(line)
            changed.append(line)
        self.assertGreater(min(late_history, future), 0)
        modified, truncated = self.work / "changed.csv", self.work / "prefix.csv"
        modified.write_text("\n".join(changed) + "\n")
        truncated.write_text("\n".join(prefix) + "\n")
        before = Model.load(original)
        available_only = History.load(truncated)
        self.assertEqual(before, Model.fit(available_only, CUTOFF))
        self.assertEqual(History.load(modified).features(issue), available_only.features(issue))
        cli("train", modified, CUTOFF, self.work)
        self.assertEqual(original.read_bytes(), (self.work / "model-v1.json").read_bytes())
        prediction = cli("predict", events, original, issue)
        for variant in (modified, truncated):
            self.assertEqual(prediction, cli("predict", variant, original, issue))
        self.assertGreater(History.load(modified).label(issue, available_only.end),
                           History.load(events).label(issue, available_only.end))
        self.assertNotEqual(cli("predict", modified, original, issue + HOUR)["prediction"],
                            cli("predict", events, original, issue + HOUR)["prediction"])

    def test_identical_rerun_and_reordered_redelivery(self) -> None:
        raw, canonical = self.work / "deliveries.csv", self.work / "events.csv"
        names = ("deliveries.csv", "events.csv", "model-v1.json", "metrics.json", "heldout.jsonl")
        for _ in range(2):
            run(INGEST, "generate", raw)
            run(INGEST, "replay", raw, canonical)
            cli("train", canonical, CUTOFF, self.work)
            for name in names:
                self.assertTrue((self.work / name).read_bytes() == (OUT / name).read_bytes(), name)
        lines = raw.read_text().splitlines()
        raw.write_text("\n".join(lines[:2] + lines[:1:-1] + lines[2:]) + "\n")
        run(INGEST, "replay", raw, canonical)
        self.assertTrue(canonical.read_bytes() == (OUT / "events.csv").read_bytes())

    def test_incompatible_artifact_or_backdated_issue_rejected(self) -> None:
        original = OUT / "model-v1.json"
        params = json.loads(original.read_text())
        path = self.work / "bad.json"
        for patch in ({"feature_schema": "other"}, {"features": params["features"][::-1]},
                      {"weights": []}, {"horizon_s": 60}, {"training_cutoff": params["last_training_origin"]}):
            path.write_text(json.dumps({**params, **patch}))
            with self.assertRaises(ValueError):
                Model.load(path)
        with self.assertRaises(ValueError):
            Model.load(original).forecast(History.load(OUT / "events.csv"), CUTOFF - HOUR)
